css:
.fx-flt{width:min(760px,100%);display:grid;grid-template-columns:1fr 1fr;gap:2.2em;align-items:start}
.fx-flt .card{--bg:color-mix(in srgb,var(--surface) 94%,var(--text));background:var(--bg);border:1px solid var(--border);border-radius:calc(var(--radius) + 2px);padding:1.6em 1.5em 1.7em;display:grid;gap:1.25em}
.fx-flt h3{font-size:1.3em}.fx-flt .sub{opacity:.62;font-size:.88em;margin-top:-.8em}
.fx-flt .f{position:relative}
.fx-flt .f input,.fx-flt .f textarea,.fx-flt .f select{width:100%;padding:1.05em .95em;border-radius:var(--radius);border:1.5px solid var(--border);background:transparent;color:var(--text);font:inherit;transition:border-color calc(.2s/var(--speed)),box-shadow calc(.2s/var(--speed))}
.fx-flt .f textarea{min-height:6.5em;resize:vertical}
.fx-flt .f label{position:absolute;left:.8em;top:1.05em;padding:0 .25em;background:var(--bg);color:color-mix(in srgb,var(--text) 58%,transparent);pointer-events:none;transform-origin:left top;transition:transform calc(.22s/var(--speed)) cubic-bezier(.2,.8,.2,1),color calc(.2s/var(--speed))}
.fx-flt .f input::placeholder,.fx-flt .f textarea::placeholder{color:transparent}
.fx-flt .f input:focus,.fx-flt .f textarea:focus{outline:none;border-color:var(--primary);box-shadow:0 0 0 3px color-mix(in srgb,var(--primary) 18%,transparent)}
.fx-flt .f input:focus+label,.fx-flt .f textarea:focus+label,.fx-flt .f input:not(:placeholder-shown)+label,.fx-flt .f textarea:not(:placeholder-shown)+label{transform:translateY(-1.55em) scale(.8)}
.fx-flt .f input:focus+label,.fx-flt .f textarea:focus+label{color:var(--primary);font-weight:700}
.fx-flt .f input:not(:placeholder-shown):not(:focus):invalid{border-color:var(--accent)}
.fx-flt .f input:not(:placeholder-shown):not(:focus):invalid+label{color:var(--accent)}
.fx-flt .f small{display:none;margin:.4em .2em 0;font-size:.78em;color:var(--accent)}
.fx-flt .f input:not(:placeholder-shown):not(:focus):invalid~small{display:block}
.fx-flt .u .f input,.fx-flt .u .f textarea{border:0;border-bottom:1.5px solid var(--border);border-radius:0;padding:1.25em .1em .5em;box-shadow:none!important}
.fx-flt .u .f label{left:.1em;top:1.2em;padding:0;background:none}
.fx-flt .u .f input:focus,.fx-flt .u .f textarea:focus{border-bottom-color:var(--primary)}
.fx-flt .u .f input:focus+label,.fx-flt .u .f textarea:focus+label,.fx-flt .u .f input:not(:placeholder-shown)+label,.fx-flt .u .f textarea:not(:placeholder-shown)+label{transform:translateY(-1.15em) scale(.78)}
.fx-flt .u .f::after{content:"";position:absolute;left:0;bottom:0;height:2px;width:100%;background:var(--primary);transform:scaleX(0);transition:transform calc(.3s/var(--speed)) ease}
.fx-flt .u .f:focus-within::after{transform:scaleX(1)}
.fx-flt .go{justify-self:start;padding:.8em 1.4em;border-radius:var(--radius);border:0;background:var(--primary);color:var(--on-primary);font:700 .92em var(--font-body);cursor:pointer}
.fx-flt .go:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
@media(max-width:700px){.fx-flt{grid-template-columns:1fr;gap:1.6em}}
@media(prefers-reduced-motion:reduce){.fx-flt .f *,.fx-flt .f::after{transition:none!important}}
